const getGrade = (s: number): string => {
  if (s >= 90) return 'O';
  if (s >= 80) return 'A+';
  if (s >= 70) return 'A';
  if (s >= 60) return 'B+';
  if (s >= 50) return 'B';
  return 'RA';
};

export const mockStudents: Student[] = rawDataset.map((row) => {
  const [
    id, dept, semester, gender,
    attendance, previousScore, internal1, internal2,
    assignment, lab, tech, code, comm, aptitude,
    backlogs, project, midterm, finalScore, category
  ] = row;

  const num = parseInt(id.replace(/\D/g, ''), 10) || 1;
  const firstName = gender === 'Female'
    ? femaleNames[num % femaleNames.length]
    : maleNames[num % maleNames.length];
  const sur = surnames[(Math.floor(num / 47) + num) % surnames.length];
  const name = `${firstName} ${sur}`;

  const assessmentScore = Math.round(((internal1 + internal2) / 2) * 10) / 10;
  const quizScore = Math.round(((aptitude + tech) / 2) * 10) / 10;
  const predictedScore = Math.round(finalScore * 10) / 10;

  const riskLevel: RiskLevel = category === 'High' ? 'LOW' : category === 'Low' ? 'HIGH' : 'MEDIUM';
  const trend: Trend = finalScore >= previousScore + 2 ? 'UP' : finalScore <= previousScore - 2 ? 'DOWN' : 'STABLE';

  const curriculum = deptCurriculums[dept] || deptCurriculums['CSE'];
  const subjectScoresRaw = [internal1, internal2, lab, project, midterm];
  const subjects: SubjectScore[] = curriculum.map((sub, i) => {
    const s = Math.min(100, Math.max(35, Math.round(subjectScoresRaw[i] || assessmentScore)));
    return {
      code: sub.code,
      name: sub.name,
      score: s,
      attendance: Math.min(100, Math.max(50, Math.round(attendance + ((i % 3) - 1) * 2))),
      grade: getGrade(s),
    };
  });

  const riskFactors: RiskFactor[] = [];
  if (attendance < 75) {
    riskFactors.push({
      factor: 'Low Attendance (<75%)',
      impact: 'HIGH IMPACT',
      description: `Attendance rate is currently at ${attendance}% (minimum statutory requirement is 75%).`,
    });
  }
  if (backlogs > 0) {
    riskFactors.push({
      factor: `${backlogs} Standing Backlog(s)`,
      impact: 'HIGH IMPACT',
      description: `Student currently has ${backlogs} pending backlog paper(s) to clear.`,
    });
  }
  if (previousScore < 60) {
    riskFactors.push({
      factor: 'Low Prior Academic Baseline',
      impact: 'MEDIUM IMPACT',
      description: `Previous semester percentage was ${previousScore}%.`,
    });
  }
  if (internal2 < internal1 - 8) {
    riskFactors.push({
      factor: 'Internal Exam Performance Drop',
      impact: 'MEDIUM IMPACT',
      description: `Internal Exam 2 (${internal2}%) dropped significantly compared to Internal Exam 1 (${internal1}%).`,
    });
  }
  if (assignment < 65) {
    riskFactors.push({
      factor: 'Low Assignment Submissions',
      impact: 'LOW IMPACT',
      description: `Assignment completion average is ${assignment}%.`,
    });
  }
  if (riskFactors.length === 0) {
    riskFactors.push({
      factor: 'Consistent Academic Trajectory',
      impact: 'LOW IMPACT',
      description: 'Student demonstrates consistent attendance, internal scores, and assignment submissions.',
    });
  }

  const year = Math.min(4, Math.max(1, Math.ceil(semester / 2)));
  const section = ['A', 'B', 'C'][num % 3];

  return {
    id,
    name,
    department: dept,
    year,
    section,
    email: `${id.toLowerCase()}@edu.in`,
    phone: `+91 9840${String(100000 + (num % 900000)).slice(-6)}`,
    emis: id,
    aadhar: `3302 ${String(4000 + (num % 5000)).padStart(4, '0')} ${String(1000 + ((num * 37) % 9000)).padStart(4, '0')}`,
    password: 'student@123',
    attendance,
    assignmentCompletion: assignment,
    previousScore,
    assessmentScore,
    quizScore,
    predictedScore,
    riskLevel,
    trend,
    subjects,
    riskFactors,
    guardianPhone: `+91 9444${String(100000 + (num % 900000)).slice(-6)}`,
    mentorName: deptMentors[dept] || 'Dr. S. Ramanathan',
    lastUpdated: '2026-11-02',
  };
});
